B:  Counting Roads

  ֤ ౎ ࢢ ͔Βଞͷ౎ ࢢ ʹԿຊͷಓ࿏͕৳ͼ͍ͯΔ͔Λௐ΂·͢ɻ·ͣɺϧʔϓΛ ࢖ ͍ͯ i(1 ≤i ≤N) ൪໨ͷ౎ ࢢ
 ʹ஫໨͠·͢ɻ ࣍ ʹɺϧʔϓΛ༻͍ͯશͯͷಓ࿏Λௐ΂͍͖ͯɺಓ࿏ͷ྆୺ʹ i ൪໨ͷ౎ ࢢ ͕ ؚ ·Ε͍ͯΔ͔Λ
 ൑ఆ͠ɺ਺͍͖͑ͯ·͢ɻͦͷ ޙ ʹɺ਺͑ͨಓ࿏ͷຊ਺Λ i(1 ≤i ≤N) ൪໨ͷ౎ ࢢ͔Β৳ͼ͍ͯΔಓ࿏ͷຊ਺ͱ
 ͯ͠ग़ྗ͠·͢ɻ͜ΕΒͷૢ࡞͸ɺ2 ॏϧʔϓΛ༻͍Δ͜ͱͰ࣮૷͕Ͱ͖·͢ɻ࣌ؒܭࢉྔ͸ O(NM) ͱͳΓɺ͜
 Ε͸ ؒʹ߹ ͍·͢ɻ

  ഑ྻΛར༻͢ΔͱɺΑΓߴ଎ʹ౴͑ΛٻΊΔ͜ͱ͕ՄೳͰ͢ɻ·ͣɺ֤౎ࢢ͔ΒԿຊͷಓ࿏͕৳ͼ͍ͯΔ͔Λ؅
 ཧ͢Δ௕͞ N ͷ഑ྻroad Λ༻ҙ͠ɺશͯͷཁૉΛ 0 ʹॳ ظ Խ͠·͢ɻ࣍ ʹɺϧʔϓΛ ࢖ͬͯશͯͷಓ࿏ʹ͍ͭ
 ͯௐ΂͍͖ͯ·͢ɻ͜ͷ࣌ɺ͋Δಓ࿏ͷ྆୺͕౎ࢢ a ͱ ౎ࢢ b ͩͬͨͱ͖ʹɺroad[a −1] ͱ road[b −1] ͷ஋Λ 1
 ૿΍͠·͢ɻ࠷ޙʹɺ֤౎ࢢ͔ΒԿຊͷಓ࿏͕৳ͼ͍ͯΔ͔Λ road Λ༻͍ͯग़ྗ͠·͢ɻ͜ͷղ๏ͷ࣌ؒܭࢉྔ
 ͸ɺO(N + M) ͱͳΓ·͢ɻ


  C++ͷίʔυྫ( ࣌ؒܭࢉ ྔO(N + M))





                                                  1

 1 int main(void) {
 2     int N, M;

 3     cin >> N >> M;


 4

 5     const int NMMAX = 50;

 6     int A[NMMAX], B[NMMAX];


 7

 8     for (int i = 0; i < M; ++i) {

 9         cin >> A[i] >> B[i];

10     }


11

12     int road[NMMAX];

13     for (int i = 0; i < N; ++i) {

14         road[i] = 0;

15     }


16

17     for (int i = 0; i < M; ++i) {

18         road[A[i] - 1] += 1;

19         road[B[i] - 1] += 1;

20     }


21

22     for (int i = 0; i < N; ++i) {

23         cout << road[i] << endl;

24     }


25

26     return 0;
27 }
